#!/usr/bin/env sh
# shellcheck disable=SC2016
set -eu

bundle_root=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
prefix=${PREFIX:-"$HOME/.local"}
bin_dir=${CMUX_LINUX_BIN_DIR:-"$prefix/bin"}
data_home=${XDG_DATA_HOME:-"$prefix/share"}
config_dir="$data_home/cmux"
prefix_metadata_dir="$prefix/share/cmux"
ghostty_dir="$config_dir/ghostty"
applications_dir="$data_home/applications"
icons_dir="$data_home/icons/hicolor/scalable/apps"
app_id=${CMUX_LINUX_APP_ID:-ai.manaflow.cmux}
renderer=${CMUX_LINUX_RENDERER:-ghostty}
socket_path=${CMUX_LINUX_SOCKET_PATH:-}

fail() {
    printf 'error: %s\n' "$*" >&2
    exit 1
}

shell_quote() {
    printf "'"
    printf '%s' "$1" | sed "s/'/'\\\\''/g"
    printf "'"
}

sed_escape() {
    printf '%s' "$1" | sed 's/[&|]/\\&/g'
}

case "$renderer" in
    gtk4) renderer=gtk ;;
    vt|libghostty-vt) renderer=ghostty-vt ;;
esac
case "$renderer" in
    core|gtk|ghostty|ghostty-vt) ;;
    *) fail "CMUX_LINUX_RENDERER must be one of: core, gtk, ghostty, ghostty-vt (got: $renderer)" ;;
esac

source_ghostty="$bundle_root/share/cmux/ghostty"
desktop_template="$bundle_root/share/cmux/ai.manaflow.cmux.desktop.in"
icon_source="$bundle_root/share/icons/hicolor/scalable/apps/ai.manaflow.cmux.svg"
version_source="$bundle_root/share/cmux/bundle-version"
provenance_source="$bundle_root/share/cmux/build-provenance.txt"

[ -x "$bundle_root/bin/cmux" ] || fail "bundle is missing bin/cmux"
[ -x "$bundle_root/bin/cmuxd-remote" ] || fail "bundle is missing bin/cmuxd-remote"
[ -x "$bundle_root/bin/cmux-linux-app" ] || fail "bundle is missing bin/cmux-linux-app"
[ -f "$source_ghostty/lib/libghostty-internal.so" ] || fail "bundle is missing libghostty-internal.so"
[ -f "$source_ghostty/include/ghostty.h" ] || fail "bundle is missing include/ghostty.h"
[ -d "$source_ghostty/share/ghostty" ] || fail "bundle is missing Ghostty runtime resources"
[ -f "$desktop_template" ] || fail "bundle is missing its desktop template"
[ -f "$icon_source" ] || fail "bundle is missing its application icon"
[ -f "$version_source" ] || fail "bundle is missing its version metadata"
[ -f "$provenance_source" ] || fail "bundle is missing its build provenance"

install -d "$bin_dir" "$config_dir" "$prefix_metadata_dir" "$applications_dir" "$icons_dir"
install -m 0755 "$bundle_root/bin/cmux" "$bin_dir/cmux"
install -m 0755 "$bundle_root/bin/cmuxd-remote" "$bin_dir/cmuxd-remote"
install -m 0755 "$bundle_root/bin/cmux-linux-app" "$bin_dir/cmux-linux-app"

source_ghostty_real=$(CDPATH='' cd -- "$source_ghostty" && pwd)
ghostty_parent_real=$(CDPATH='' cd -- "$config_dir" && pwd)
ghostty_dir_real="$ghostty_parent_real/ghostty"
if [ "$source_ghostty_real" != "$ghostty_dir_real" ]; then
    install -d "$ghostty_dir"
    cp -a "$source_ghostty/." "$ghostty_dir/"
fi

config_tmp=$(mktemp)
desktop_tmp=$(mktemp)
trap 'rm -f "$config_tmp" "$desktop_tmp"' EXIT INT TERM
{
    printf '# Generated by the cmux Linux bundle installer\n'
    printf 'CMUX_LINUX_RENDERER=${CMUX_LINUX_RENDERER:-%s}\n' "$(shell_quote "$renderer")"
    printf 'export CMUX_LINUX_RENDERER\n'
    printf 'CMUX_GHOSTTY_LIBRARY=${CMUX_GHOSTTY_LIBRARY:-%s}\n' \
        "$(shell_quote "$ghostty_dir/lib/libghostty-internal.so")"
    printf 'export CMUX_GHOSTTY_LIBRARY\n'
    if [ -f "$ghostty_dir/lib/libghostty-vt.so" ]; then
        printf 'CMUX_GHOSTTY_VT_LIBRARY=${CMUX_GHOSTTY_VT_LIBRARY:-%s}\n' \
            "$(shell_quote "$ghostty_dir/lib/libghostty-vt.so")"
        printf 'export CMUX_GHOSTTY_VT_LIBRARY\n'
    fi
    printf 'CMUX_GHOSTTY_ROOT=${CMUX_GHOSTTY_ROOT:-%s}\n' "$(shell_quote "$ghostty_dir")"
    printf 'export CMUX_GHOSTTY_ROOT\n'
    if [ -n "$socket_path" ]; then
        printf 'CMUX_SOCKET_PATH=${CMUX_SOCKET_PATH:-%s}\n' "$(shell_quote "$socket_path")"
        printf 'export CMUX_SOCKET_PATH\n'
    fi
} > "$config_tmp"
install -m 0644 "$config_tmp" "$config_dir/linux-app.env"
install -m 0644 "$version_source" "$config_dir/bundle-version"
install -m 0644 "$provenance_source" "$config_dir/build-provenance.txt"
if [ "$prefix_metadata_dir" != "$config_dir" ]; then
    install -m 0644 "$version_source" "$prefix_metadata_dir/bundle-version"
    install -m 0644 "$provenance_source" "$prefix_metadata_dir/build-provenance.txt"
fi

install -m 0644 "$icon_source" "$icons_dir/$app_id.svg"
sed \
    -e "s|@CMUX_APP_WRAPPER@|$(sed_escape "$bin_dir/cmux-linux-app")|g" \
    -e "s|@APP_ID@|$(sed_escape "$app_id")|g" \
    "$desktop_template" > "$desktop_tmp"
install -m 0644 "$desktop_tmp" "$applications_dir/$app_id.desktop"

if command -v update-desktop-database >/dev/null 2>&1; then
    update-desktop-database "$applications_dir" >/dev/null 2>&1 || true
fi

printf 'Installed cmux Linux bundle:\n'
printf '  launcher: %s/cmux-linux-app\n' "$bin_dir"
printf '  ghostty:  %s/lib/libghostty-internal.so\n' "$ghostty_dir"
printf '  desktop:  %s/%s.desktop\n' "$applications_dir" "$app_id"
printf '\nRun with: %s/cmux-linux-app\n' "$bin_dir"
